INSERT INTO `categories` VALUES (1,'chamanthi-flowers','Chamanthi Flowers',NULL,'Shop Yellow, Pink, Violet and Red Chamanthi flowers in Hyderabad for pooja, garlands, festival decoration and traditional occasions.','<p>Choose Chamanthi by colour. Each colour keeps one permanent page so customers can find the correct flower without duplicate URLs.</p>',0,6,3,'chamanthi',1,'2024-11-19 12:09:42','2026-09-25 19:23:30'),(2,'pooja-roses','Pooja Roses',NULL,'Order Button Roses and Mixed Roses in Hyderabad for pooja, petals, garlands, archana and traditional flower decoration.','<p>This section focuses on loose roses and rose buds for pooja and traditional use, separate from bouquet and gifting pages.</p>',0,6,5,'roses',1,'2024-11-19 12:10:24','2026-09-25 19:23:30'),(3,'banthi','Banthi',NULL,'Banthi flower category.','Banthi flower category.',0,6,13,'banthi',0,'2024-12-13 17:23:02','2026-09-25 19:23:30'),(4,'other-flowers','Other Flowers',NULL,NULL,NULL,0,NULL,NULL,'other-flowers',0,'2024-12-13 17:23:35','2026-09-25 19:23:30'),(5,'pooja-leaves','Pooja Leaves','category-patri.jpg','Order fresh Betel Leaves, Tulasi Patri, Maredu Patri and Arati Akulu in Hyderabad for pooja and traditional ceremonies.','<p>Browse fresh pooja leaves using familiar English and local names without creating duplicate pages for Tamalapakulu, Bilva, Vilvam or other aliases.</p>',0,6,12,'pooja-leaves',1,'2024-12-13 17:34:12','2026-09-25 19:29:16'),(6,'pooja-flowers','Pooja Flowers','category-daily-puja.jpg','Order fresh pooja flowers in Hyderabad including Lotus, Chamanthi, Sampangi, Jasmine, Roses and traditional flowers from Manidvipa Flowers.','<p>Shop fresh flowers for daily pooja, temple offerings, festivals and traditional functions. Browse by flower family and open the exact flower page for current availability and selling options.</p>',1,NULL,1,'pooja-flowers',1,'2026-08-19 18:43:15','2026-09-25 19:23:30'),(7,'premium-flowers','Premium Flowers','category-premium.jpg','Explore premium flower selections in Hyderabad for pooja, special occasions and floral arrangements. Inventory will be published as verified premium varieties are added.','<p>This category is prepared for premium flower inventory. Keep it noindex until genuine premium items, images, prices and availability are added.</p>',1,NULL,10,'premium-flowers',1,'2026-08-20 19:59:24','2026-09-25 19:23:30'),(8,'rare-flowers','Rare Flowers','category-rare.jpg','Explore limited-availability and harder-to-source traditional flowers in Hyderabad. Check current stock with Manidvipa Flowers before ordering.','<p>A curated collection for traditional flowers that may have limited, seasonal or irregular supply. Availability changes, so the collection should be driven by active inventory tags.</p>',1,NULL,9,'rare-flowers',1,'2026-08-20 22:09:35','2026-09-25 19:23:30'),(9,'bouquets-gifts','Bouquets & Gifts','category-gifting.jpg','Explore flower bouquets and floral gifts in Hyderabad for birthdays, anniversaries and special occasions. Verified designs will be published here.','<p>Bouquets and gifts have different buying intent from pooja flowers. Keep this page noindex until genuine bouquet and gifting inventory is added.</p>',1,NULL,16,'bouquets-gifts',1,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(10,'garlands','Garlands','category-temple.jpg','Explore fresh flower garlands in Hyderabad for pooja, temple offerings, weddings and traditional functions. Verified garland options will be published here.','<p>Garlands are separate sellable items, not duplicate loose-flower pages. Keep this page noindex until real garland types, sizes, images and prices are loaded.</p>',1,NULL,15,'garlands',1,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(11,'kanakambaram','Kanakambaram',NULL,'Kanakambaram flower category.','Kanakambaram flower category.',0,6,14,'kanakambaram',0,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(12,'lotus-flowers','Lotus Flowers',NULL,'Order fresh White Lotus and Pink Lotus flowers in Hyderabad for pooja, temple offerings and traditional ceremonies from Manidvipa Flowers.','<p>Browse White Lotus and Pink Lotus as separate colour varieties with their own availability, images and ordering information.</p>',0,6,2,'lotus',1,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(13,'jasmine-sannajaji','Jasmine & Sannajaji',NULL,'Order fresh Jasmine, Malli, Mallelu and Sannajaji flowers in Hyderabad for pooja, garlands, flower strings and traditional occasions.','<p>Find fragrant Jasmine and Sannajaji while keeping familiar local names such as Malli and Mallelu connected to the correct page.</p>',0,6,6,'jasmine',1,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(14,'seasonal-flowers','Seasonal Flowers',NULL,'Explore seasonal flowers in Hyderabad for pooja, festivals and traditional occasions. Availability changes with season and fresh market supply.','<p>A dynamic collection for flowers whose supply changes by season. The page should show only currently relevant flowers and link to their canonical detail pages.</p>',1,NULL,11,'seasonal-flowers',1,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(15,'tuberose','Tuberose',NULL,'Tuberose flower category.','Tuberose flower category.',0,151,23,'tuberose',0,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(16,'sampangi-flowers','Sampangi Flowers',NULL,'Order fresh Yellow Sampangi and Green Sampangi flowers in Hyderabad for pooja, garlands and traditional floral use.','<p>Browse Yellow and Green Sampangi in one family collection, then open the exact colour page for current stock and pack sizes.</p>',0,6,4,'sampangi',1,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(17,'tulips','Tulips',NULL,'Tulips flower category.','Tulips flower category.',0,7,31,'tulips',0,'2026-08-21 05:22:27','2026-09-27 04:23:40'),(18,'orchids','Orchids',NULL,'Orchids flower category.','Orchids flower category.',0,7,32,'orchids',0,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(19,'lilies','Lilies',NULL,'Lilies flower category.','Lilies flower category.',0,7,33,'lilies',0,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(20,'imported-exotic-flowers','Imported & Exotic Flowers',NULL,'Explore imported and exotic flower varieties in Hyderabad as verified inventory becomes available from Manidvipa Flowers.','<p>A future-ready collection for genuine imported or exotic flowers. Do not index it until real inventory and original images are present.</p>',1,NULL,17,'imported-exotic-flowers',1,'2026-08-21 05:22:27','2026-09-25 19:23:30'),(151,'fragrant-flowers','fragrance',NULL,'Explore fragrant flowers in Hyderabad including Jasmine, Sannajaji and Sampangi for pooja, garlands and traditional floral use.','<p>Browse naturally fragrant traditional flowers. This page is a collection only: every flower continues to use its single Pooja Flowers canonical URL.</p>',1,NULL,8,'fragrant-flowers',1,'2026-09-22 17:16:02','2026-09-25 19:33:31'),(152,'traditional','Pooja Decorated Flowers',NULL,'Shop Red Mandaram, Pooja Lilies, Nandivardhanam and Pink Arali in Hyderabad for traditional pooja, offerings and ceremonial flower use.','<p>A dedicated family for traditional flower varieties that do not need a separate large colour-family category.</p>',0,6,7,'traditional',1,'2026-09-25 19:23:30','2026-09-28 09:15:34'),(153,'pooja-herbs','Pooja Herbs',NULL,'Order fresh Maruvam and Davanam in Hyderabad for pooja, garlands and traditional flower combinations from Manidvipa Flowers.','<p>A dedicated section for aromatic pooja greens such as Maruvam and Davanam, separate from loose flower pages.</p>',0,6,13,'pooja-herbs',1,'2026-09-25 19:23:30','2026-09-25 19:29:36'),(154,'pooja-essentials','Pooja Essentials',NULL,'Shop traditional pooja flower and plant essentials in Hyderabad, including Arati Padulu for functions and ceremonial decoration.','<p>Traditional floral and plant-based pooja requirements that are neither loose flowers nor pooja leaves belong here.</p>',0,6,14,'pooja-essentials',1,'2026-09-25 19:23:30','2026-09-25 19:29:51');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
UNLOCK TABLES;

