INSERT INTO `content_blocks` VALUES (1,'Addresses - Footer','<div class=\"footer-address-info\"><h4>Manidvipa Flowers - Hyderabad</h4><p>Vengal Rao Nagar, SR Nagar, Hyderabad - 500038, Telangana, India.</p><p>Phone: +91 94917 47624 &nbsp; | &nbsp; Email: manidvipaservices@gmail.com</p></div>',1,'2023-06-03 08:01:18','2026-09-25 19:23:32'),(2,'Why Choose Us','<div class=\"section-title-area\"><h2>Why Manidvipa Flowers?</h2><p>Fresh flower-focused catalog, clear local flower names, daily availability, practical selling options and convenient Hyderabad ordering.</p><ul><li>Fresh pooja flowers and traditional varieties</li><li>Local-name search support such as Malli, Mallelu, Tamalapakulu and Bilva</li><li>Seasonal availability shown honestly</li><li>Flowers, pooja leaves, garlands and gifting categories in one place</li></ul></div>',1,'2024-04-04 19:10:04','2026-09-25 19:23:32'),(3,'About Us - Home Page','<div class=\"section-title-area\"><h2>About Manidvipa Flowers</h2><p>Manidvipa Flowers serves Hyderabad customers looking for fresh pooja flowers, traditional flowers, pooja leaves, fragrant varieties and floral essentials. Our catalog is organised by familiar flower names so customers can find the right variety quickly.</p></div>',1,'2024-04-12 22:39:25','2026-09-25 19:23:32'),(4,'Features - Home','<div class=\"row\"><div class=\"col-md-4\"><h4>Fresh Market Availability</h4><p>Flower stock and prices can change with daily market arrivals.</p></div><div class=\"col-md-4\"><h4>Clear Flower Varieties</h4><p>Choose the exact flower, colour and available selling option.</p></div><div class=\"col-md-4\"><h4>Hyderabad Ordering</h4><p>Order for serviceable Hyderabad locations based on current availability.</p></div></div>',1,'2024-04-12 22:43:17','2026-09-25 19:23:32');
/*!40000 ALTER TABLE `content_blocks` ENABLE KEYS */;
UNLOCK TABLES;

