INSERT INTO `faqs` VALUES (1,'Do you deliver fresh pooja flowers in Hyderabad?','Manidvipa Flowers serves serviceable Hyderabad locations. Delivery availability can depend on the flower, order quantity, location and requested date.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32'),(2,'Can I order flowers for daily pooja?','Yes. Browse the Pooja Flowers section for Lotus, Chamanthi, Sampangi, Jasmine, Roses and other traditional flower varieties based on current availability.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32'),(3,'Why does flower availability change?','Fresh flowers are seasonal and daily market supply can vary with weather, harvest and demand. Product pages should show the current availability instead of promising permanent stock.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32'),(4,'Can I order pooja leaves and herbs separately?','Yes. Pooja Leaves and Pooja Herbs are separate sections for items such as Betel Leaves, Tulasi Patri, Maredu Patri, Maruvam and Davanam.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32'),(5,'Do you sell garlands and bouquets?','Garlands and Bouquets & Gifts are separate categories because prepared floral products are different from loose pooja flowers. Availability depends on the current catalog.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32'),(6,'How do I confirm the latest price?','Use the currently displayed selling option on the product page or contact Manidvipa Flowers. Fresh flower prices can change with daily market conditions.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32'),(7,'Can I search using Telugu or local flower names?','Yes. Common local names and spelling variants are included in product search terms and redirects so names such as Malli, Mallelu, Tamalapakulu and Bilva lead to the correct item.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32'),(8,'Can I place a bulk flower order?','Bulk requirements can be discussed based on flower type, quantity, date and current supply. Contact Manidvipa Flowers before time-sensitive functions or temple requirements.',1,'2026-09-25 19:23:32','2026-09-25 19:23:32');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

