INSERT INTO `mf_categories` VALUES (1,'POOJA','Pooja Flowers','/pooja-flowers',NULL,'primary','Fresh Pooja Flowers Online in Hyderabad | Manidvipa Flowers','Fresh Pooja Flowers in Hyderabad','Order fresh pooja flowers in Hyderabad including Lotus, Chamanthi, Sampangi, Jasmine, Roses and traditional flowers from Manidvipa Flowers.','pooja flowers in Hyderabad','<p>Shop fresh flowers for daily pooja, temple offerings, festivals and traditional functions. Browse by flower family and open the exact flower page for current availability and selling options.</p>',1,1,1,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(2,'LOTUS','Lotus Flowers','/pooja-flowers/lotus','POOJA','family','Lotus Flowers Hyderabad | White & Pink Lotus for Pooja','Fresh Lotus Flowers in Hyderabad','Order fresh White Lotus and Pink Lotus flowers in Hyderabad for pooja, temple offerings and traditional ceremonies from Manidvipa Flowers.','lotus flowers in Hyderabad','<p>Browse White Lotus and Pink Lotus as separate colour varieties with their own availability, images and ordering information.</p>',1,1,2,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(3,'CHAMANTHI','Chamanthi Flowers','/pooja-flowers/chamanthi','POOJA','family','Chamanthi Flowers Hyderabad | Yellow, Pink, Violet & Red','Fresh Chamanthi Flowers in Hyderabad','Shop Yellow, Pink, Violet and Red Chamanthi flowers in Hyderabad for pooja, garlands, festival decoration and traditional occasions.','chamanthi flowers in Hyderabad','<p>Choose Chamanthi by colour. Each colour keeps one permanent page so customers can find the correct flower without duplicate URLs.</p>',1,1,3,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(4,'SAMPANGI','Sampangi Flowers','/pooja-flowers/sampangi','POOJA','family','Sampangi Flowers Hyderabad | Yellow & Green Sampangi','Fresh Sampangi Flowers in Hyderabad','Order fresh Yellow Sampangi and Green Sampangi flowers in Hyderabad for pooja, garlands and traditional floral use.','sampangi flowers in Hyderabad','<p>Browse Yellow and Green Sampangi in one family collection, then open the exact colour page for current stock and pack sizes.</p>',1,1,4,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(5,'ROSES','Pooja Roses','/pooja-flowers/roses','POOJA','family','Roses for Pooja in Hyderabad | Button Roses & Mixed Roses','Fresh Roses for Pooja in Hyderabad','Order Button Roses and Mixed Roses in Hyderabad for pooja, petals, garlands, archana and traditional flower decoration.','roses for pooja in Hyderabad','<p>This section focuses on loose roses and rose buds for pooja and traditional use, separate from bouquet and gifting pages.</p>',1,1,5,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(6,'JASMINE','Jasmine & Sannajaji','/pooja-flowers/jasmine','POOJA','family','Jasmine Flowers Hyderabad | Malli, Mallelu & Sannajaji','Fresh Jasmine & Sannajaji Flowers in Hyderabad','Order fresh Jasmine, Malli, Mallelu and Sannajaji flowers in Hyderabad for pooja, garlands, flower strings and traditional occasions.','jasmine flowers in Hyderabad','<p>Find fragrant Jasmine and Sannajaji while keeping familiar local names such as Malli and Mallelu connected to the correct page.</p>',1,1,6,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(7,'TRADITIONAL','Traditional Pooja Flowers','/pooja-flowers/traditional','POOJA','family','Traditional Pooja Flowers Hyderabad | Manidvipa Flowers','Traditional Pooja Flowers in Hyderabad','Shop Red Mandaram, Pooja Lilies, Nandivardhanam and Pink Arali in Hyderabad for traditional pooja, offerings and ceremonial flower use.','traditional pooja flowers in Hyderabad','<p>A dedicated family for traditional flower varieties that do not need a separate large colour-family category.</p>',1,1,7,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(8,'FRAGRANT','Fragrant Flowers','/fragrant-flowers',NULL,'collection','Fragrant Flowers Hyderabad | Jasmine, Sampangi & Sannajaji','Fresh Fragrant Flowers in Hyderabad','Explore fragrant flowers in Hyderabad including Jasmine, Sannajaji and Sampangi for pooja, garlands and traditional floral use.','fragrant flowers in Hyderabad','<p>Browse naturally fragrant traditional flowers. This page is a collection only: every flower continues to use its single Pooja Flowers canonical URL.</p>',1,1,8,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(9,'RARE','Rare Flowers','/rare-flowers',NULL,'collection','Rare Flowers in Hyderabad | Traditional & Limited Flowers','Rare & Limited-Availability Flowers in Hyderabad','Explore limited-availability and harder-to-source traditional flowers in Hyderabad. Check current stock with Manidvipa Flowers before ordering.','rare flowers in Hyderabad','<p>A curated collection for traditional flowers that may have limited, seasonal or irregular supply. Availability changes, so the collection should be driven by active inventory tags.</p>',1,1,9,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(10,'PREMIUM','Premium Flowers','/premium-flowers',NULL,'collection','Premium Flowers in Hyderabad | Manidvipa Flowers','Premium Flowers in Hyderabad','Explore premium flower selections in Hyderabad for pooja, special occasions and floral arrangements. Inventory will be published as verified premium varieties are added.','premium flowers in Hyderabad','<p>This category is prepared for premium flower inventory. Keep it noindex until genuine premium items, images, prices and availability are added.</p>',0,1,10,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(11,'SEASONAL','Seasonal Flowers','/seasonal-flowers',NULL,'collection','Seasonal Flowers in Hyderabad | Manidvipa Flowers','Seasonal Flowers in Hyderabad','Explore seasonal flowers in Hyderabad for pooja, festivals and traditional occasions. Availability changes with season and fresh market supply.','seasonal flowers in Hyderabad','<p>A dynamic collection for flowers whose supply changes by season. The page should show only currently relevant flowers and link to their canonical detail pages.</p>',1,1,11,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(12,'LEAVES','Pooja Leaves','/pooja-leaves',NULL,'primary','Fresh Pooja Leaves Hyderabad | Tulasi, Maredu, Betel & More','Fresh Pooja Leaves in Hyderabad','Order fresh Betel Leaves, Tulasi Patri, Maredu Patri and Arati Akulu in Hyderabad for pooja and traditional ceremonies.','pooja leaves in Hyderabad','<p>Browse fresh pooja leaves using familiar English and local names without creating duplicate pages for Tamalapakulu, Bilva, Vilvam or other aliases.</p>',1,1,12,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(13,'HERBS','Pooja Herbs','/pooja-herbs',NULL,'primary','Fresh Pooja Herbs Hyderabad | Maruvam & Davanam','Fresh Maruvam & Davanam in Hyderabad','Order fresh Maruvam and Davanam in Hyderabad for pooja, garlands and traditional flower combinations from Manidvipa Flowers.','pooja herbs in Hyderabad','<p>A dedicated section for aromatic pooja greens such as Maruvam and Davanam, separate from loose flower pages.</p>',1,1,13,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(14,'ESSENTIALS','Pooja Essentials','/pooja-essentials',NULL,'primary','Pooja Essentials Hyderabad | Traditional Floral Essentials','Traditional Pooja Essentials in Hyderabad','Shop traditional pooja flower and plant essentials in Hyderabad, including Arati Padulu for functions and ceremonial decoration.','pooja essentials in Hyderabad','<p>Traditional floral and plant-based pooja requirements that are neither loose flowers nor pooja leaves belong here.</p>',1,1,14,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(15,'GARLANDS','Garlands','/garlands',NULL,'primary','Fresh Flower Garlands in Hyderabad | Manidvipa Flowers','Fresh Flower Garlands in Hyderabad','Explore fresh flower garlands in Hyderabad for pooja, temple offerings, weddings and traditional functions. Verified garland options will be published here.','flower garlands in Hyderabad','<p>Garlands are separate sellable items, not duplicate loose-flower pages. Keep this page noindex until real garland types, sizes, images and prices are loaded.</p>',0,1,15,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(16,'BOUQUETS','Bouquets & Gifts','/bouquets-gifts',NULL,'primary','Flower Bouquets & Gifts in Hyderabad | Manidvipa Flowers','Flower Bouquets & Gifts in Hyderabad','Explore flower bouquets and floral gifts in Hyderabad for birthdays, anniversaries and special occasions. Verified designs will be published here.','flower bouquets in Hyderabad','<p>Bouquets and gifts have different buying intent from pooja flowers. Keep this page noindex until genuine bouquet and gifting inventory is added.</p>',0,1,16,'2026-09-25 18:55:33','2026-09-25 18:55:33'),(17,'EXOTIC','Imported & Exotic Flowers','/imported-exotic-flowers',NULL,'collection','Imported & Exotic Flowers Hyderabad | Manidvipa Flowers','Imported & Exotic Flowers in Hyderabad','Explore imported and exotic flower varieties in Hyderabad as verified inventory becomes available from Manidvipa Flowers.','exotic flowers in Hyderabad','<p>A future-ready collection for genuine imported or exotic flowers. Do not index it until real inventory and original images are present.</p>',0,1,17,'2026-09-25 18:55:33','2026-09-25 18:55:33');
