INSERT INTO `pages` VALUES (1,'About Us','<div class=\"col-lg-6 col-md-6 col-sm-12\">\r\n<p data-end=\"219\" data-start=\"184\"><strong data-end=\"219\" data-start=\"184\">Where Every Bloom Tells a Story</strong></p>\r\n\r\n<p data-end=\"370\" data-start=\"221\">Welcome to <strong data-end=\"253\" data-start=\"232\">Manidvipa Flowers</strong>, your go-to floral destination for fresh, premium-quality flowers delivered right to your doorstep&mdash;every single day.</p>\r\n\r\n<p data-end=\"701\" data-start=\"372\">Founded in 2023, Manidvipa Flowers was born out of a simple yet powerful belief: that flowers have the magic to uplift, heal, and celebrate life. Whether you&#39;re looking for divine blooms for your pooja rituals, vibrant petals for a special celebration, or just a bunch to brighten someone&rsquo;s day, we&rsquo;re here to make it meaningful.</p>\r\n\r\n<h3 data-end=\"807\" data-start=\"774\">Sourced Straight from Farmers</h3>\r\n\r\n<p data-end=\"1127\" data-start=\"809\">What makes us special? <strong data-end=\"878\" data-start=\"832\">We work directly with farmers across India</strong>, cutting out the middlemen to ensure you get only the <strong data-end=\"969\" data-start=\"933\">freshest and most vibrant blooms</strong> at the best value. Our deep connection with local growers allows us to source a wide variety of flowers every day, hand-selected for their quality and charm.</p>\r\n\r\n<p data-end=\"1318\" data-start=\"1129\">From <strong data-end=\"1151\" data-start=\"1134\">pooja flowers</strong>, <strong data-end=\"1173\" data-start=\"1153\">wedding garlands</strong>, and <strong data-end=\"1194\" data-start=\"1179\">event decor</strong>, to <strong data-end=\"1215\" data-start=\"1199\">loose petals</strong> and <strong data-end=\"1251\" data-start=\"1220\">premium floral arrangements</strong>, we offer a diverse range to suit every tradition and celebration.</p>\r\n\r\n<p data-end=\"1351\" data-start=\"1320\">Our flower collection includes:</p>\r\n\r\n<ul data-end=\"1780\" data-start=\"1352\">\r\n	<li data-end=\"1430\" data-start=\"1352\">\r\n	<p data-end=\"1430\" data-start=\"1354\"><strong data-end=\"1373\" data-start=\"1354\">Oriental Lilies</strong> &ndash; Luxurious, fragrant, and perfect for premium gifting</p>\r\n	</li>\r\n	<li data-end=\"1496\" data-start=\"1431\">\r\n	<p data-end=\"1496\" data-start=\"1433\"><strong data-end=\"1458\" data-start=\"1433\">Jasmine (Malli Puvvu)</strong> &ndash; Ideal for pooja and daily rituals</p>\r\n	</li>\r\n	<li data-end=\"1562\" data-start=\"1497\">\r\n	<p data-end=\"1562\" data-start=\"1499\"><strong data-end=\"1525\" data-start=\"1499\">Rajnigandha (Tuberose)</strong> &ndash; Symbol of purity and celebration</p>\r\n	</li>\r\n	<li data-end=\"1635\" data-start=\"1563\">\r\n	<p data-end=\"1635\" data-start=\"1565\"><strong data-end=\"1585\" data-start=\"1565\">Marigold (Genda)</strong> &ndash; A must for festive decor and temple offerings</p>\r\n	</li>\r\n	<li data-end=\"1682\" data-start=\"1636\">\r\n	<p data-end=\"1682\" data-start=\"1638\"><strong data-end=\"1647\" data-start=\"1638\">Roses</strong> &ndash; Classic beauty in every colour</p>\r\n	</li>\r\n	<li data-end=\"1716\" data-start=\"1683\">\r\n	<p data-end=\"1716\" data-start=\"1685\"><strong data-end=\"1694\" data-start=\"1685\">Lotus</strong> &ndash; Sacred and serene</p>\r\n	</li>\r\n	<li data-end=\"1780\" data-start=\"1717\">\r\n	<p data-end=\"1780\" data-start=\"1719\"><strong data-end=\"1737\" data-start=\"1719\">Chrysanthemums</strong>, <strong data-end=\"1753\" data-start=\"1739\">Carnations</strong>, <strong data-end=\"1767\" data-start=\"1755\">Gerberas</strong>, and more...</p>\r\n	</li>\r\n</ul>\r\n\r\n<h3 data-end=\"725\" data-start=\"703\">What Sets Us Apart</h3>\r\n\r\n<p data-end=\"1100\" data-start=\"727\">At Manidvipa, we don&rsquo;t just sell flowers&mdash;we deliver moments, emotions, and traditions wrapped in freshness. Every stem is hand-picked with care, ethically sourced from trusted growers, and beautifully packed to preserve nature&rsquo;s charm. Our collection features everything from spiritual flowers to ornamental blooms, all curated with devotion and a deep respect for culture.</p>\r\n\r\n<h3 data-end=\"1124\" data-start=\"1102\">Our Promise to You</h3>\r\n\r\n<p data-end=\"1426\" data-start=\"1126\">Your satisfaction is our blooming priority. From the moment you place your order to the joyful moment you unwrap your flowers, we ensure a smooth, thoughtful, and delightful experience. Our team pays attention to every detail so that each delivery carries not just flowers, but also warmth and grace.</p>\r\n\r\n<h3 data-end=\"1454\" data-start=\"1428\">Join Our Floral Family</h3>\r\n\r\n<p data-end=\"1705\" data-start=\"1456\">We&rsquo;d love to grow with you! Be part of the <strong data-end=\"1520\" data-start=\"1499\">Manidvipa Flowers</strong> community by sharing your floral moments with us on social media. Tag us and use our official hashtag <strong data-end=\"1644\" data-start=\"1623\">#ManidvipaFlowers</strong> to help spread joy, tradition, and love&mdash;one petal at a time.</p>\r\n\r\n<p data-end=\"1871\" data-start=\"1707\">Thank you for choosing Manidvipa Flowers. With your support, we continue to bring divine freshness, cultural richness, and floral elegance to homes across the city.</p>\r\n</div>',1,'about-us','2023-09-20 03:01:07','2024-03-07 15:39:11'),(2,'Refund & Return Policy','<p data-end=\"584\" data-start=\"220\">At <strong data-end=\"259\" data-start=\"238\">Manidvipa Flowers</strong>, customer satisfaction is at the heart of everything we do. We are committed to delivering fresh, high-quality floral products across Hyderabad. However, we understand that unforeseen situations&mdash;such as weather issues, delivery disruptions, or stock unavailability&mdash;may occasionally affect timely delivery or product quality.</p>\n\n<p data-end=\"822\" data-start=\"586\">We sincerely apologize for any inconvenience this may cause and have a clear policy in place to address such instances. If you are not satisfied with your order, you may request a return or refund in line with the policy outlined below.</p>\n\n<hr data-end=\"827\" data-start=\"824\" />\n<h3 data-end=\"860\" data-start=\"829\"><strong data-end=\"858\" data-start=\"833\">Delivery and Shipping</strong></h3>\n\n<p data-end=\"928\" data-start=\"861\">We currently offer flower delivery services across <strong data-end=\"925\" data-start=\"912\">Hyderabad</strong>.</p>\n\n<ul data-end=\"1228\" data-start=\"929\">\n	<li data-end=\"1061\" data-start=\"929\">\n	<p data-end=\"1061\" data-start=\"931\"><strong data-end=\"951\" data-start=\"931\">Delivery charges</strong> are calculated based on the delivery location (PIN code) and order size. Charges will be shown at checkout.</p>\n	</li>\n	<li data-end=\"1158\" data-start=\"1062\">\n	<p data-end=\"1158\" data-start=\"1064\"><strong data-end=\"1090\" data-start=\"1064\">Standard delivery time</strong>: Between 0&ndash;2 days, depending on the order type and delivery area.</p>\n	</li>\n	<li data-end=\"1228\" data-start=\"1159\">\n	<p data-end=\"1228\" data-start=\"1161\">Any unexpected delays will be communicated via call, SMS, or email.</p>\n	</li>\n</ul>\n\n<hr data-end=\"1233\" data-start=\"1230\" />\n<h3 data-end=\"1264\" data-start=\"1235\"><strong data-end=\"1262\" data-start=\"1239\">Order Cancellations</strong></h3>\n\n<ul data-end=\"1413\" data-start=\"1265\">\n	<li data-end=\"1349\" data-start=\"1265\">\n	<p data-end=\"1349\" data-start=\"1267\">You can cancel your order <strong data-end=\"1346\" data-start=\"1293\">up to 12 hours before the scheduled delivery time</strong>.</p>\n	</li>\n	<li data-end=\"1413\" data-start=\"1350\">\n	<p data-end=\"1413\" data-start=\"1352\">Orders <strong data-end=\"1381\" data-start=\"1359\">cannot be canceled</strong> once they are out for delivery.</p>\n	</li>\n</ul>\n\n<hr data-end=\"1418\" data-start=\"1415\" />\n<h3 data-end=\"1437\" data-start=\"1420\"><strong data-end=\"1435\" data-start=\"1424\">Refunds</strong></h3>\n\n<ul data-end=\"1723\" data-start=\"1438\">\n	<li data-end=\"1539\" data-start=\"1438\">\n	<p data-end=\"1539\" data-start=\"1440\">Refunds are applicable <strong data-end=\"1471\" data-start=\"1463\">only</strong> if the product is defective or if the order is <strong data-end=\"1536\" data-start=\"1519\">not delivered</strong>.</p>\n	</li>\n	<li data-end=\"1625\" data-start=\"1540\">\n	<p data-end=\"1625\" data-start=\"1542\">You must contact us within <strong data-end=\"1593\" data-start=\"1569\">24 hours of delivery</strong> to initiate a refund request.</p>\n	</li>\n	<li data-end=\"1723\" data-start=\"1626\">\n	<p data-end=\"1723\" data-start=\"1628\">Approved refunds will be credited to your original payment method within <strong data-end=\"1722\" data-start=\"1701\">1&ndash;2 business days</strong>.</p>\n	</li>\n</ul>\n\n<hr data-end=\"1728\" data-start=\"1725\" />\n<h3 data-end=\"1747\" data-start=\"1730\"><strong data-end=\"1745\" data-start=\"1734\">Returns</strong></h3>\n\n<p data-end=\"1867\" data-start=\"1748\">Due to the <strong data-end=\"1780\" data-start=\"1759\">perishable nature</strong> of flowers, we do <strong data-end=\"1821\" data-start=\"1799\">not accept returns</strong>, unless there is a <strong data-end=\"1866\" data-start=\"1841\">quality-related issue</strong>.</p>\n\n<hr data-end=\"1872\" data-start=\"1869\" />\n<h3 data-end=\"1906\" data-start=\"1874\"><strong data-end=\"1904\" data-start=\"1878\">Bad Quality of Flowers</strong></h3>\n\n<p data-end=\"2114\" data-start=\"1907\">If the flowers received are <strong data-end=\"1954\" data-start=\"1935\">wilted, damaged</strong>, or not up to expected standards (due to weather or human error), we are happy to replace them with another item of equal value or process a <strong data-end=\"2111\" data-start=\"2096\">full refund</strong>.</p>\n\n<ul data-end=\"2326\" data-start=\"2115\">\n	<li data-end=\"2172\" data-start=\"2115\">\n	<p data-end=\"2172\" data-start=\"2117\">Requests must be made within <strong data-end=\"2169\" data-start=\"2146\">2 hours of delivery</strong>.</p>\n	</li>\n	<li data-end=\"2326\" data-start=\"2173\">\n	<p data-end=\"2326\" data-start=\"2175\">As we may not always be able to arrange a doorstep exchange immediately, you may be requested to <strong data-end=\"2307\" data-start=\"2272\">return the product to our store</strong> for a replacement.</p>\n	</li>\n</ul>\n\n<hr data-end=\"2331\" data-start=\"2328\" />\n<h3 data-end=\"2383\" data-start=\"2333\"><strong data-end=\"2381\" data-start=\"2337\">Incorrect or Substituted Floral Products</strong></h3>\n\n<p data-end=\"2527\" data-start=\"2384\">On rare occasions, if your selected floral product is out of stock and we&rsquo;re unable to reach you in time, we may send a <strong data-end=\"2524\" data-start=\"2504\">close substitute</strong>.</p>\n\n<ul data-end=\"2653\" data-start=\"2528\">\n	<li data-end=\"2653\" data-start=\"2528\">\n	<p data-end=\"2653\" data-start=\"2530\">If you are not satisfied with the substituted product, you may follow the same return or refund process as mentioned above.</p>\n	</li>\n</ul>\n\n<hr data-end=\"2658\" data-start=\"2655\" />\n<h3 data-end=\"2706\" data-start=\"2660\"><strong data-end=\"2704\" data-start=\"2664\">Important Note for Special Occasions</strong></h3>\n\n<p data-end=\"3024\" data-start=\"2707\">For events like <strong data-end=\"2735\" data-start=\"2723\">weddings</strong>, <strong data-end=\"2752\" data-start=\"2737\">engagements</strong>, or <strong data-end=\"2769\" data-start=\"2757\">concerts</strong>, please understand that exact replication of floral arrangements shown on the website may not always be possible due to seasonal or stock-related limitations. However, we guarantee that your arrangement will closely match the discussed style and quality.</p>\n\n<hr data-end=\"3029\" data-start=\"3026\" />\n<h3 data-end=\"3061\" data-start=\"3031\"><strong data-end=\"3059\" data-start=\"3035\">Account Registration</strong></h3>\n\n<p data-end=\"3287\" data-start=\"3062\">To place an online order, simply register with your <strong data-end=\"3139\" data-start=\"3114\">email ID and password</strong>. Once your first order is complete, you&rsquo;ll receive a <strong data-end=\"3213\" data-start=\"3193\">reference number</strong> for easy access during future purchases. Registration is free and secure.</p>\n\n<hr data-end=\"3292\" data-start=\"3289\" />\n<h3 data-end=\"3320\" data-start=\"3294\"><strong data-end=\"3318\" data-start=\"3298\">Need Assistance?</strong></h3>\n\n<p data-end=\"3503\" data-start=\"3321\">We&rsquo;re here to help!<br data-end=\"3343\" data-start=\"3340\" />\nIf you have any questions, feel free to reach out via email or use the <strong data-end=\"3427\" data-start=\"3414\">live chat</strong> option on our portal <strong data-end=\"3502\" data-start=\"3449\"><a data-end=\"3500\" data-start=\"3451\" href=\"https://manidvipaflowers.com\" rel=\"noopener\" target=\"_new\">Manidvipa Flowers</a></strong>.</p>\n\n<p data-end=\"3607\" data-start=\"3505\">Thank you for choosing <strong data-end=\"3549\" data-start=\"3528\">Manidvipa Flowers</strong>&mdash;where tradition, freshness, and fragrance meet every day.</p>',1,'refund-return-policy','2023-09-20 03:21:11','2024-02-14 10:29:02'),(3,'Privacy Policy','<p data-end=\"607\" data-start=\"236\">This Privacy Policy is a part of the Terms of Use and governs the manner in which <strong data-end=\"339\" data-start=\"318\">Manidvipa Flowers</strong> collects, uses, maintains, and discloses information collected from users of our website <strong data-end=\"493\" data-start=\"429\"><a data-end=\"491\" data-start=\"431\" href=\"https://www.manidvipaflowers.com\" rel=\"noopener\" target=\"_new\">www.manidvipaflowers.com</a></strong> (hereinafter referred to as the &quot;Website&quot;). By using this Website, you agree to the terms of this Privacy Policy.</p>\r\n\r\n<p data-end=\"794\" data-start=\"609\">Please note: This policy may be updated from time to time without prior notice. We encourage you to review this page periodically to stay informed about how we protect your information.</p>\r\n\r\n<hr data-end=\"799\" data-start=\"796\" />\r\n<h2 data-end=\"833\" data-start=\"801\"><strong data-end=\"833\" data-start=\"804\">1. Information Collection</strong></h2>\r\n\r\n<p data-end=\"968\" data-start=\"835\">We collect personally identifiable information (PII) such as your name, email address, phone number, and delivery address when you:</p>\r\n\r\n<ul data-end=\"1076\" data-start=\"969\">\r\n	<li data-end=\"996\" data-start=\"969\">\r\n	<p data-end=\"996\" data-start=\"971\">Register on our website</p>\r\n	</li>\r\n	<li data-end=\"1015\" data-start=\"997\">\r\n	<p data-end=\"1015\" data-start=\"999\">Place an order</p>\r\n	</li>\r\n	<li data-end=\"1047\" data-start=\"1016\">\r\n	<p data-end=\"1047\" data-start=\"1018\">Subscribe to our newsletter</p>\r\n	</li>\r\n	<li data-end=\"1076\" data-start=\"1048\">\r\n	<p data-end=\"1076\" data-start=\"1050\">Contact our support team</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1225\" data-start=\"1078\">We may also gather information about your preferences and previous orders to serve you better with personalized offers and product recommendations.</p>\r\n\r\n<hr data-end=\"1230\" data-start=\"1227\" />\r\n<h2 data-end=\"1268\" data-start=\"1232\"><strong data-end=\"1268\" data-start=\"1235\">2. Purpose of Data Collection</strong></h2>\r\n\r\n<p data-end=\"1310\" data-start=\"1270\">The information we collect is used to:</p>\r\n\r\n<ul data-end=\"1542\" data-start=\"1311\">\r\n	<li data-end=\"1346\" data-start=\"1311\">\r\n	<p data-end=\"1346\" data-start=\"1313\">Process your orders efficiently</p>\r\n	</li>\r\n	<li data-end=\"1383\" data-start=\"1347\">\r\n	<p data-end=\"1383\" data-start=\"1349\">Improve your shopping experience</p>\r\n	</li>\r\n	<li data-end=\"1428\" data-start=\"1384\">\r\n	<p data-end=\"1428\" data-start=\"1386\">Send you updates about your order status</p>\r\n	</li>\r\n	<li data-end=\"1485\" data-start=\"1429\">\r\n	<p data-end=\"1485\" data-start=\"1431\">Share promotional offers, deals, and seasonal alerts</p>\r\n	</li>\r\n	<li data-end=\"1542\" data-start=\"1486\">\r\n	<p data-end=\"1542\" data-start=\"1488\">Respond to customer service requests and support needs</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"1547\" data-start=\"1544\" />\r\n<h2 data-end=\"1573\" data-start=\"1549\"><strong data-end=\"1573\" data-start=\"1552\">3. Communications</strong></h2>\r\n\r\n<h3 data-end=\"1614\" data-start=\"1575\"><strong data-end=\"1612\" data-start=\"1579\">Service-Related Announcements</strong></h3>\r\n\r\n<p data-end=\"1803\" data-start=\"1615\">We may send service-related notifications (e.g., order confirmation, delivery updates, website maintenance alerts) that are essential to complete your transaction or maintain your account.</p>\r\n\r\n<h3 data-end=\"1842\" data-start=\"1805\"><strong data-end=\"1840\" data-start=\"1809\">Promotional Emails &amp; Offers</strong></h3>\r\n\r\n<p data-end=\"2036\" data-start=\"1843\">We may occasionally send promotional content, special deals, and seasonal flower offers. You can opt out of such marketing communications at any time using the &ldquo;unsubscribe&rdquo; link in our emails.</p>\r\n\r\n<hr data-end=\"2041\" data-start=\"2038\" />\r\n<h2 data-end=\"2060\" data-start=\"2043\"><strong data-end=\"2060\" data-start=\"2046\">4. Cookies</strong></h2>\r\n\r\n<p data-end=\"2366\" data-start=\"2062\">Our Website uses cookies to enhance your browsing experience. Cookies are small text files stored on your device that help us remember your preferences and analyze website traffic. You may choose to disable cookies through your browser settings, although this may affect some functionalities of the site.</p>\r\n\r\n<hr data-end=\"2371\" data-start=\"2368\" />\r\n<h2 data-end=\"2391\" data-start=\"2373\"><strong data-end=\"2391\" data-start=\"2376\">5. Security</strong></h2>\r\n\r\n<p data-end=\"2618\" data-start=\"2393\">We value your trust and take your privacy seriously. While we do not collect sensitive financial information like credit card or Aadhaar numbers, we maintain appropriate security measures to protect your personal information.</p>\r\n\r\n<p data-end=\"2741\" data-start=\"2620\"><strong data-end=\"2629\" data-start=\"2620\">Note:</strong> We do not use encryption on our forms since we do not request sensitive data that could lead to identity theft.</p>\r\n\r\n<hr data-end=\"2746\" data-start=\"2743\" />\r\n<h2 data-end=\"2779\" data-start=\"2748\"><strong data-end=\"2779\" data-start=\"2751\">6. Access and Correction</strong></h2>\r\n\r\n<p data-end=\"2980\" data-start=\"2781\">If your personal information changes, or if you no longer wish to use our service, you can update, correct, or delete your details by contacting our customer support at <strong data-end=\"2979\" data-start=\"2950\"><a data-end=\"2977\" data-start=\"2952\" rel=\"noopener\">info@manidvipaflowers.com</a></strong>.</p>\r\n\r\n<hr data-end=\"2985\" data-start=\"2982\" />\r\n<h2 data-end=\"3011\" data-start=\"2987\"><strong data-end=\"3011\" data-start=\"2990\">7. Policy Changes</strong></h2>\r\n\r\n<p data-end=\"3279\" data-start=\"3013\">Manidvipa Flowers reserves the right to update or change this Privacy Policy at any time. Any material changes will be posted on the homepage or notified via email. Continued use of the Website following the changes constitutes your acceptance of the revised policy.</p>\r\n\r\n<hr data-end=\"3284\" data-start=\"3281\" />\r\n<h2 data-end=\"3313\" data-start=\"3286\"><strong data-end=\"3313\" data-start=\"3289\">8. Grievance Officer</strong></h2>\r\n\r\n<p data-end=\"3465\" data-start=\"3315\">In accordance with the Information Technology Act, 2000, and applicable rules, the contact details of the designated Grievance Officer are as follows:</p>\r\n\r\n<p data-end=\"3554\" data-start=\"3467\"><strong data-end=\"3475\" data-start=\"3467\">Name</strong>: Mr. Mohan<br data-end=\"3489\" data-start=\"3486\" />\r\n<strong data-end=\"3498\" data-start=\"3489\">Phone</strong>: +91-94917 47624<br data-end=\"3518\" data-start=\"3515\" />\r\n<strong data-end=\"3527\" data-start=\"3518\">Email</strong>: <a data-end=\"3554\" data-start=\"3529\" rel=\"noopener\">info@manidvipaflowers.com</a></p>\r\n\r\n<hr data-end=\"3559\" data-start=\"3556\" />\r\n<p data-end=\"3746\" data-start=\"3561\">If you have any questions, concerns, or complaints regarding this Privacy Policy or the handling of your personal information, please contact the Grievance Officer at the details above.</p>',1,'privacy-policy','2023-09-20 03:30:57','2024-02-14 10:27:32'),(4,'Terms & Conditions','<p data-end=\"426\" data-start=\"158\">Welcome to <strong data-end=\"193\" data-start=\"169\">ManidvipaFlowers.com</strong> (&quot;we,&quot; &quot;us,&quot; &quot;our&quot;). These Terms and Conditions govern your access to and use of our website, services, and products, including any content, features, and functionality offered on or through <strong data-end=\"409\" data-start=\"385\">manidvipaflowers.com</strong> (the &quot;Website&quot;).</p>\r\n\r\n<p data-end=\"585\" data-start=\"428\">By accessing or using the Website, you agree to be bound by these Terms and Conditions. If you do not agree with these Terms, please do not use our services.</p>\r\n\r\n<hr data-end=\"590\" data-start=\"587\" />\r\n<h3 data-end=\"618\" data-start=\"592\">1. General Information</h3>\r\n\r\n<p data-end=\"799\" data-start=\"619\"><strong data-end=\"643\" data-start=\"619\">ManidvipaFlowers.com</strong> is an online platform that offers premium fresh flowers, pooja flowers, and related floral services to customers. We are based in <strong data-end=\"798\" data-start=\"774\">Hyderabad, Telangana</strong>.</p>\r\n\r\n<ul data-end=\"927\" data-start=\"801\">\r\n	<li data-end=\"840\" data-start=\"801\">\r\n	<p data-end=\"840\" data-start=\"803\"><strong data-end=\"820\" data-start=\"803\">Company Name:</strong> Manidvipa Flowers</p>\r\n	</li>\r\n	<li data-end=\"881\" data-start=\"841\">\r\n	<p data-end=\"881\" data-start=\"843\"><strong data-end=\"853\" data-start=\"843\">Email:</strong> <a data-end=\"879\" data-start=\"854\" rel=\"noopener\">info@manidvipaflowers.com</a></p>\r\n	</li>\r\n	<li data-end=\"927\" data-start=\"882\">\r\n	<p data-end=\"927\" data-start=\"884\"><strong data-end=\"909\" data-start=\"884\">Customer Care Number:</strong> +91 94917 47624</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"932\" data-start=\"929\" />\r\n<h3 data-end=\"961\" data-start=\"934\">2. Account Registration</h3>\r\n\r\n<p data-end=\"1089\" data-start=\"962\">To access certain features of the Website (such as placing orders), you must create an account. When registering, you agree to:</p>\r\n\r\n<ul data-end=\"1255\" data-start=\"1091\">\r\n	<li data-end=\"1147\" data-start=\"1091\">\r\n	<p data-end=\"1147\" data-start=\"1093\">Provide accurate, current, and complete information.</p>\r\n	</li>\r\n	<li data-end=\"1193\" data-start=\"1148\">\r\n	<p data-end=\"1193\" data-start=\"1150\">Keep your login credentials confidential.</p>\r\n	</li>\r\n	<li data-end=\"1255\" data-start=\"1194\">\r\n	<p data-end=\"1255\" data-start=\"1196\">Be fully responsible for all activities under your account.</p>\r\n	</li>\r\n</ul>\r\n\r\n<p data-end=\"1334\" data-start=\"1257\">We reserve the right to suspend or terminate accounts that violate our terms.</p>\r\n\r\n<hr data-end=\"1339\" data-start=\"1336\" />\r\n<h3 data-end=\"1369\" data-start=\"1341\">3. Products and Services</h3>\r\n\r\n<p data-end=\"1621\" data-start=\"1370\">ManidvipaFlowers.com offers premium fresh flowers and pooja items. We strive to display product descriptions and images as accurately as possible. However, we do not guarantee that all content, including product details or pricing, will be error-free.</p>\r\n\r\n<hr data-end=\"1626\" data-start=\"1623\" />\r\n<h3 data-end=\"1654\" data-start=\"1628\">4. Orders and Payments</h3>\r\n\r\n<p data-end=\"1808\" data-start=\"1656\"><strong data-end=\"1677\" data-start=\"1656\">Order Acceptance:</strong><br data-end=\"1680\" data-start=\"1677\" />\r\nAll orders are subject to availability and confirmation. We reserve the right to cancel or reject orders at our sole discretion.</p>\r\n\r\n<p data-end=\"2018\" data-start=\"1810\"><strong data-end=\"1830\" data-start=\"1810\">Payment Options:</strong><br data-end=\"1833\" data-start=\"1830\" />\r\nWe accept online payments through a secure Razorpay payment gateway. All transactions are processed in <strong data-end=\"1959\" data-start=\"1936\">Indian Rupees (INR)</strong> and inclusive of applicable taxes unless stated otherwise.</p>\r\n\r\n<p data-end=\"2043\" data-start=\"2020\"><strong data-end=\"2041\" data-start=\"2020\">Accepted Methods:</strong></p>\r\n\r\n<ul data-end=\"2148\" data-start=\"2044\">\r\n	<li data-end=\"2091\" data-start=\"2044\">\r\n	<p data-end=\"2091\" data-start=\"2046\">Credit/Debit Cards (Visa, MasterCard, Amex)</p>\r\n	</li>\r\n	<li data-end=\"2099\" data-start=\"2092\">\r\n	<p data-end=\"2099\" data-start=\"2094\">UPI</p>\r\n	</li>\r\n	<li data-end=\"2115\" data-start=\"2100\">\r\n	<p data-end=\"2115\" data-start=\"2102\">Net Banking</p>\r\n	</li>\r\n	<li data-end=\"2148\" data-start=\"2116\">\r\n	<p data-end=\"2148\" data-start=\"2118\">Digital Wallets (via Razorpay)</p>\r\n	</li>\r\n</ul>\r\n\r\n<hr data-end=\"2153\" data-start=\"2150\" />\r\n<h3 data-end=\"2183\" data-start=\"2155\">5. Delivery and Shipping</h3>\r\n\r\n<p data-end=\"2348\" data-start=\"2185\">We currently deliver within <strong data-end=\"2238\" data-start=\"2213\">Hyderabad city limits</strong>. Delivery charges are calculated based on the delivery location and order size and are displayed at checkout.</p>\r\n\r\n<p data-end=\"2438\" data-start=\"2350\"><strong data-end=\"2381\" data-start=\"2350\">Standard Delivery Timeline:</strong><br data-end=\"2384\" data-start=\"2381\" />\r\n0&ndash;2 business days from the date of order confirmation.</p>\r\n\r\n<p data-end=\"2599\" data-start=\"2440\"><strong data-end=\"2449\" data-start=\"2440\">Note:</strong> We are not responsible for delivery delays caused by circumstances beyond our control (e.g., weather disruptions, strikes, natural calamities, etc.).</p>\r\n\r\n<hr data-end=\"2604\" data-start=\"2601\" />\r\n<h3 data-end=\"2648\" data-start=\"2606\">6. Cancellations, Refunds, and Returns</h3>\r\n\r\n<p data-end=\"2801\" data-start=\"2650\"><strong data-end=\"2668\" data-start=\"2650\">Cancellations:</strong><br data-end=\"2671\" data-start=\"2668\" />\r\nOrders can be canceled up to <strong data-end=\"2747\" data-start=\"2700\">12 hours before the scheduled delivery time</strong>. Orders that are out for delivery cannot be canceled.</p>\r\n\r\n<p data-end=\"3052\" data-start=\"2803\"><strong data-end=\"2815\" data-start=\"2803\">Refunds:</strong><br data-end=\"2818\" data-start=\"2815\" />\r\nRefunds are only applicable in the event of a defective product or failed delivery. Refund requests must be raised within <strong data-end=\"2952\" data-start=\"2940\">24 hours</strong> of delivery. Refunds will be processed to the original payment method within <strong data-end=\"3051\" data-start=\"3030\">1&ndash;2 business days</strong>.</p>\r\n\r\n<p data-end=\"3178\" data-start=\"3054\"><strong data-end=\"3066\" data-start=\"3054\">Returns:</strong><br data-end=\"3069\" data-start=\"3066\" />\r\nDue to the perishable nature of our products, we do not accept returns unless there&#39;s a proven quality issue.</p>\r\n\r\n<hr data-end=\"3183\" data-start=\"3180\" />\r\n<h3 data-end=\"3213\" data-start=\"3185\">7. Intellectual Property</h3>\r\n\r\n<p data-end=\"3404\" data-start=\"3215\">All content on this Website&mdash;text, images, logos, graphics, and software&mdash;is the property of Manidvipa Flowers or its content suppliers. Any unauthorized use may result in legal consequences.</p>\r\n\r\n<hr data-end=\"3409\" data-start=\"3406\" />\r\n<h3 data-end=\"3432\" data-start=\"3411\">8. Privacy Policy</h3>\r\n\r\n<p data-end=\"3638\" data-start=\"3434\">Our <a data-end=\"3499\" data-start=\"3438\" rel=\"noopener\" target=\"_new\">Privacy Policy</a> explains how we collect and use your personal data. By using this site, you agree to our data practices as outlined in the Privacy Policy.</p>\r\n\r\n<hr data-end=\"3643\" data-start=\"3640\" />\r\n<h3 data-end=\"3675\" data-start=\"3645\">9. Limitation of Liability</h3>\r\n\r\n<p data-end=\"3904\" data-start=\"3677\">To the fullest extent permitted by law, ManidvipaFlowers.com and its representatives shall not be liable for any indirect, incidental, or consequential damages arising out of the use or inability to use our Website or services.</p>\r\n\r\n<hr data-end=\"3909\" data-start=\"3906\" />\r\n<h3 data-end=\"3949\" data-start=\"3911\">10. Governing Law and Jurisdiction</h3>\r\n\r\n<p data-end=\"4128\" data-start=\"3951\">These Terms and Conditions shall be governed by the laws of <strong data-end=\"4020\" data-start=\"4011\">India</strong>, and any disputes shall be subject to the exclusive jurisdiction of the courts in <strong data-end=\"4127\" data-start=\"4103\">Hyderabad, Telangana</strong>.</p>\r\n\r\n<hr data-end=\"4133\" data-start=\"4130\" />\r\n<h3 data-end=\"4174\" data-start=\"4135\">11. Changes to Terms and Conditions</h3>\r\n\r\n<p data-end=\"4425\" data-start=\"4176\">We reserve the right to modify these Terms and Conditions at any time. Changes will be posted on this page, and it is your responsibility to check them periodically. Continued use of the Website after updates implies acceptance of the revised Terms.</p>\r\n\r\n<hr data-end=\"4430\" data-start=\"4427\" />\r\n<h3 data-end=\"4459\" data-start=\"4432\">12. Contact Information</h3>\r\n\r\n<p data-end=\"4539\" data-start=\"4461\">For questions or concerns about these Terms and Conditions, please contact us:</p>\r\n\r\n<ul data-end=\"4702\" data-start=\"4541\">\r\n	<li data-end=\"4581\" data-start=\"4541\">\r\n	<p data-end=\"4581\" data-start=\"4543\"><strong data-end=\"4553\" data-start=\"4543\">Email:</strong> <a data-end=\"4579\" data-start=\"4554\" rel=\"noopener\">info@manidvipaflowers.com</a></p>\r\n	</li>\r\n	<li data-end=\"4612\" data-start=\"4582\">\r\n	<p data-end=\"4612\" data-start=\"4584\"><strong data-end=\"4594\" data-start=\"4584\">Phone:</strong> +91 94917 47624</p>\r\n	</li>\r\n	<li data-end=\"4702\" data-start=\"4613\">\r\n	<p data-end=\"4702\" data-start=\"4615\"><strong data-end=\"4635\" data-start=\"4615\">Mailing Address:</strong> Vengal Rao Nagar, SR Nagar, Hyderabad &ndash; 500038, Telangana, India</p>\r\n	</li>\r\n</ul>',1,'terms-conditions','2023-09-22 07:51:16','2024-02-14 10:29:13'),(5,'Contact Us',NULL,1,'contact-us','2024-04-02 05:32:03','2024-05-24 10:25:23');
