INSERT INTO `site_content` VALUES ('FRESHNESS','Freshness Comes First','<p>Flowers and leaves are natural and seasonal. Prices, colour shades, size and stock can change with market arrivals. We show current sellable options instead of locking changing market information into marketing copy.</p>',1,'2026-09-25 18:02:58'),('HOME_HERO','Fresh Flowers for Pooja & Tradition','<p>Fresh lotus, chamanthi, sampangi, jasmine, roses, pooja leaves and traditional flower varieties for Hyderabad customers—organised by the names people actually use.</p>',1,'2026-09-25 18:02:58'),('SEO_PROMISE','Built for People First','<p>Our catalog avoids duplicate pages for the same flower. Familiar names such as Malli, Mallelu, Tamalapakulu, Bilva, Purple Samanthi and Dhavanam are connected to the correct page so customers can search naturally.</p>',1,'2026-09-25 18:02:58'),('WHY_MANIDVIPA','Why Manidvipa Flowers','<p>Clear flower names, local-name search support, honest daily availability, practical selling units and one permanent URL for every sellable item.</p>',1,'2026-09-25 18:02:58');
/*!40000 ALTER TABLE `site_content` ENABLE KEYS */;
UNLOCK TABLES;

