INSERT INTO `subscription_plans` VALUES (1,'Corporate Starter Premium Arrangement','corporate-starter-premium-arrangement','Corporate Offices','Premium Arrangements','Premium','A compact premium reception arrangement for small offices and clinics.','Designed for businesses that need a professional reception look without buying loose flowers. This package is arrangement-based and refreshed on a fixed schedule.',6999.00,'/ month',NULL,NULL,'Monthly','2 refreshes per week','Not sold by kg; includes finished arrangement service','1 reception arrangement per refresh','Small / Medium reception bowl or vase','2 refreshes per week','Gerbera\r\nPremium roses\r\nLilies based on availability\r\nSeasonal fillers','Extra desk or cabin arrangements are quoted separately based on size and flower choice.','1 month','1 finished reception arrangement\r\nPremium seasonal flower selection\r\nVase/bowl styling support\r\nScheduled refresh service','Professional office presentation\r\nNo loose flower handling required\r\nDedicated WhatsApp coordination\r\nFlower varieties depend on market availability','Small corporate offices\r\nClinics\r\nShowrooms\r\nReception desks','Request Starter Plan',NULL,2,1,1,'2026-08-20 23:08:42','2026-09-14 13:14:13'),(2,'Hospital & Clinic Floral Service','hospital-clinic-floral-service','Hospitals','Premium Arrangements','Standard / Premium','Reception and prayer-area floral refresh for hospitals and clinics.','A clean, predictable flower service for hospital reception areas, prayer rooms and visitor spaces. Plans are configured by arrangement count and refresh schedule.',9999.00,'/ month',NULL,NULL,'Monthly','2-3 refreshes per week','Finished arrangements; optional puja flowers can be added','1 reception arrangement + optional puja flower add-on','Medium reception arrangement','2-3 refreshes per week','Lilies\r\nGerbera\r\nRoses\r\nOrchids on request\r\nSeasonal fillers','Daily puja flowers, garlands or additional reception arrangements are billed separately.','1 month','Reception arrangement\r\nPrayer-area flower option\r\nScheduled refresh support\r\nHygienic packing','Clean presentation\r\nFixed delivery window\r\nMonthly billing support\r\nCustom quantity add-ons','Hospitals\r\nClinics\r\nWellness centers\r\nDiagnostic centers','Request Hospital Plan',NULL,3,1,1,'2026-08-20 23:08:42','2026-09-14 13:14:24'),(3,'Temple Daily Loose Flower Plan','temple-daily-loose-flower-plan','Temples','Loose Flowers','Fresh Daily','Loose flowers, garlands and patri for daily temple pooja.','A quantity-based subscription for temples and daily pooja needs. This is the correct plan type when pricing depends on kg, garlands or leaves.',1199.00,'/ month',NULL,NULL,'Monthly','Daily morning delivery','Starts with 500g loose flowers per delivery','Garlands and leaves can be added as required','Not applicable','Daily delivery','Chamanthi\r\nBanthi\r\nKanakambaram\r\nJasmine\r\nTulasi\r\nBilva leaves','Extra kg, garlands and patri are billed as per daily market price.','1 month','Loose flowers\r\nPatri and leaves option\r\nGarlands option\r\nFestival bulk planning','Quantity-based pricing\r\nDaily fresh sourcing\r\nCustom flower mix\r\nFestival bulk support','Temples\r\nDaily pooja\r\nApartments\r\nPuja mandirs','Request Temple Plan',NULL,1,1,1,'2026-08-20 23:08:42','2026-09-14 13:13:52'),(4,'Hotel Lobby Premium Arrangement Plan','hotel-lobby-premium-arrangement-plan','Hotels','Premium Arrangements','Premium / Imported Mix','Premium lobby and front-desk arrangements for hospitality spaces.','A premium arrangement service for hotels, restaurants and banquet spaces that need fresh lobby or front-desk presentation.',18999.00,'/ month',NULL,NULL,'Monthly','2-4 refreshes per week','Arrangement-based service; not kg-based','1 lobby/front desk arrangement per refresh','Large front desk / lobby arrangement','2-4 refreshes per week','Oriental lilies\r\nOrchids\r\nAnthuriums\r\nPremium roses\r\nSeasonal exotic fillers','Restaurant table flowers and banquet upgrades are quoted separately.','1 month','Lobby/front desk arrangement\r\nPremium flower selection\r\nRefresh schedule\r\nTheme support','Hospitality-grade presentation\r\nCustom color palette\r\nEvent upgrade support\r\nDedicated coordination','Hotels\r\nRestaurants\r\nBanquet halls\r\nGuest houses','Request Hotel Plan',NULL,5,1,1,'2026-08-20 23:08:42','2026-09-14 13:14:57'),(5,'Custom Enterprise Flower Plan','custom-enterprise-flower-plan','Business Bulk','Custom / Hybrid','As per requirement','Custom premium arrangements, loose flowers or bulk flower supply for large accounts.','For businesses with mixed needs: premium arrangements, daily puja flowers, garlands, events or imported flower requirements.',0.00,'/ month',NULL,NULL,'Custom','Custom schedule','Final quantity and arrangement scope decided after requirement discussion','Custom','Custom','Custom','Oriental lilies\r\nOrchids\r\nTulips\r\nLoose pooja flowers\r\nGarlands\r\nSeasonal premium flowers','Quote depends on flower type, quantity, location, refresh frequency and imported flower availability.','Discuss with team','Custom plan design\r\nPremium or loose flower supply\r\nBulk/event support\r\nFlexible delivery schedule','Best for unclear requirements\r\nQuote after discussion\r\nSupports premium and loose flowers\r\nDedicated account support','Large corporate offices\r\nHospitals\r\nHotels\r\nEvent venues\r\nBulk buyers','Request Custom Quote',NULL,7,1,1,'2026-08-20 23:08:42','2026-09-14 13:15:22'),(6,'Corporate Premium Flower Arrangement Plan','corporate-premium-flower-arrangement-plan','Corporate Offices','Premium Arrangements','Premium / Imported Mix','Reception plus desk/lounge arrangements using lilies, orchids and premium roses.','Built for corporate offices that want a consistent premium look in reception, lounge or boardroom spaces. This is arrangement-based, not loose flower supply.',14999.00,'/ month',NULL,NULL,'Monthly','3 refreshes per week','Not sold by kg; includes multiple finished arrangements','1 reception arrangement + 2 desk/lounge arrangements','Medium reception + small desk arrangements','3 refreshes per week','Oriental lilies\r\nOrchids\r\nPremium roses\r\nAnthuriums\r\nGerbera\r\nSeasonal fillers','Imported tulips or exotic flowers are added as per availability and quoted before confirmation.','1 month recommended; 3 months for fixed imported flower planning','Reception arrangement\r\n2 desk or lounge arrangements\r\nPremium flower mix\r\nRefresh and replacement planning','Premium business presentation\r\nCustom color theme\r\nMonthly billing support\r\nPriority sourcing for premium flowers','Corporate offices\r\nHospitals\r\nPremium clinics\r\nBusiness lounges','Request Premium Plan',NULL,4,1,1,'2026-08-20 23:08:42','2026-09-14 13:14:44'),(7,'Elite Imported Flower Arrangement Plan','elite-imported-flower-arrangement-plan','Corporate Offices','Premium Arrangements','Imported / Exotic','Large lobby, boardroom and cabin arrangements with imported premium flowers.','For corporates, hotels and premium spaces that need a high-end floral presentation with imported flowers and custom refresh schedules.',25000.00,'/ month',NULL,NULL,'Monthly','Custom refresh schedule','Custom arrangement scope; finalized after site requirement','Lobby arrangement + boardroom/cabin arrangements as quoted','Large lobby / premium boardroom / custom','2-5 refreshes per week based on flower type','Oriental lilies\r\nImported orchids\r\nTulips\r\nAnthuriums\r\nImported roses\r\nHydrangea on request','Imported flower pricing changes by season and availability. Final quotation confirms exact varieties.','3 months recommended','Premium lobby arrangement\r\nBoardroom or cabin arrangements\r\nImported flower planning\r\nCustom color/theme direction','High-end corporate presentation\r\nImported flower sourcing\r\nDedicated account support\r\nCustom billing and delivery schedule','Corporate headquarters\r\nHotels\r\nLuxury showrooms\r\nPremium hospitals','Request Elite Quote',NULL,6,1,1,'2026-08-20 23:08:42','2026-09-14 13:15:07');
