INSERT INTO `testimonials` VALUES (3,'Deepthi Chandu','House WIfe','House WIfe','person-suit-male1707386362.jpg','Great quality products and amazing customer service. Very happy with my purchase and will definitely recommend it to all my friends. They showed me all products on video call and gave for very reasonable prices. They were able to deliver everything before expected date.',1,NULL,'2023-09-20 05:24:15','2024-02-08 09:59:25'),(4,'Mohan Rao Vangara',NULL,'Software Engineer','front-view-face-close1707386446.jpg','I really got impressed with range of items available. Staff are very courteous and cooperative in showing range of items with patience.Shop owners maintenance much relationship with customers which leading in building long loyal customers base. Happy to write this review.',1,NULL,'2023-09-20 05:25:19','2024-02-08 10:00:46'),(5,'Shruthi Naidu',NULL,'Us Resident','man-glasses-portrait1707386515.jpg','Sandeep is an amazing person and very responsive. I live the US and he was very patient enough to show me all the items requested for. The package sent all the way was in good state and great quality. I will continue to buy stuff from his store',1,NULL,'2023-09-20 05:25:50','2024-02-08 10:01:56');
